@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: (
    'inline-padding': (property: padding-inline-start padding-inline-end, class: project-px, values: (2: .5rem)),
    'cursor': (property: cursor, values: pointer wait),
    'type-size': (property: (font-size: 1rem, line-height: 1.5), class: project-type, values: (small: (font-size: .875rem)))
  )
);

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: (
    'project-tone': (
      property: ('--project-tone': null, color: var(--project-tone)),
      class: project-tone, values: (brand: #075985)
    )
  )
);

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: (
    'project-pattern': (
      selector: attr-starts, class: 'project-card-',
      property: padding-inline-start, values: 6px
    )
  )
);

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: (
    'project-space': (
      property: margin-block-start, class: project-space,
      child-selector: '> * + *', responsive: true, state: hover,
      values: (3: 1rem)
    )
  )
);

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: (
    'project-cursor': (property: cursor, class: project-cursor, responsive: true, values: (pointer: pointer)),
    'project-fade': (property: opacity, class: project-fade, responsive: true, print: true, dark: true, state: hover focus-visible, values: (50: .5))
  )
);

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: (
    'float': null,
    'opacity': (property: opacity, class: opacity, state: hover, values: (50: .5, 100: 1)),
    'cursor': (enabled: false)
  )
);

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: (
    'project-display': (property: display, class: project-display, important: true, values: (flex: flex))
  )
);

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: (
    'project-motion': (property: animation, class: project-motion, responsive: true, state: hover, values: (pop: animation-pop .3s ease both))
  )
);

/* Application preference rule for the normal-priority example above. */
@media (prefers-reduced-motion: reduce) {
  .project-motion-demo { animation: none !important; }
}

@use 'tremplin/scss/theme' with (
  $theme-colors: (brand: (base: #253a76, fg: #253a76, bg: #dce6ff, contrast: #17213b))
);
@use 'tremplin/scss/tremplin-utilities';

.demo-contrast {
  --trm-primary-bg: var(--trm-blue-700);
  --trm-success-bg: var(--trm-green-700);
  --trm-danger-bg: var(--trm-red-700);
  --trm-primary-fg: var(--trm-primary-fg-emphasis);
  --trm-success-fg: var(--trm-success-fg-emphasis);
  --trm-danger-fg: var(--trm-danger-fg-emphasis);
  --trm-info-fg: var(--trm-info-fg-emphasis);
  --trm-warning-fg: var(--trm-warning-fg-emphasis);
  --trm-link-color: var(--trm-primary-fg-emphasis);
  --trm-link-hover-color: var(--trm-primary-fg-emphasis);
}
.demo-contrast [data-trm-theme][dir] {
  color: var(--trm-fg-body);
  background-color: var(--trm-bg-body);
}
/* Calendar Pro appends input popups to body, outside the wrapper. Its styles
   option carries this explicit class to both popup and inline calendars. */
.demo-calendar-contrast[data-vc="calendar"] {
  --trm-datepicker-day-selected-bg: var(--trm-blue-700);
  --trm-datepicker-day-disabled-color: var(--trm-fg-2);
}
.demo-calendar-contrast [data-vc-date-month="prev"] [data-vc-date-btn],
.demo-calendar-contrast [data-vc-date-month="next"] [data-vc-date-btn] {
  opacity: .8;
}

@use 'tremplin/scss/config' with ($gradient: linear-gradient(135deg, #e6efff, #fff));
@use 'tremplin/scss/mixins/gradients' as gradient;
@use 'tremplin/scss/tremplin-utilities';
.three-color-x { @include gradient.gradient-x-three-colors(red, gold, 40%, blue); }
.three-color-y { @include gradient.gradient-y-three-colors(red, gold, 60%, blue); }

